INSERT INTO `cq_quiz` VALUES (650,9,2,0,'In~which~channel~can~all~the~players~in~the~same~server~see~messages?','Team','Broadcast','Guild','Talk',2),(651,9,2,0,'In~which~channel~can~only~selected~targets~receive~messages?','Talk','Broadcast','Whisper','Friends',3),(652,9,2,0,'How~many~ways~are~there~to~target~a~player~you~wish~to~talk~to?','1','2','3','4',4),(653,9,2,0,'Which~button~do~we~use~to~clear~the~chat~and~system~messages~on~the~screen?','Clear','Chat','Talk','Team',1),(654,9,2,0,'Which~status~shows~the~magic~strength~of~characters?','Spirit','Vitality','Agility','Strength',1),(655,9,2,0,'Which~button~can~we~use~to~end~a~friendship?','Made~Friends','FriendsList','Delete','Check',3),(656,9,2,0,'When~will~your~friends~receive~your~offline~message?','Immediately','Two~Days','Three~Days','Next~time~they~login',4),(657,9,2,0,'How~many~enemies~can~the~enemy~list~hold?','20','30','15','25',1),(658,9,2,0,'How~many~apprentices~can~level~70-109~characters~have?','One','Two','Three','Four',2),(659,9,2,0,'How~many~friends~can~you~have~at~most~on~your~friends~list?','50','20','100','25',1),(660,9,2,0,'How~many~PK~points~will~you~get~when~you~kill~a~player?','5','10','15','20',2),(661,9,2,0,'If~your~PK~points~are~higher~than~100,~your~character~will~be?','White~name','Red~name','Blue~name','Black~name',4),(662,9,2,0,'If~your~equipment~is~detained~by~the~system,~whom~can~you~find~to~redeem~it?','Confiscator','Warehouseman','Boxer','General~Judd',1),(663,9,2,0,'How~many~pieces~of~equipment~will~be~detained~when~you~are~killed~while~black~named~with~over~300~PK~points?','1','2','3','4',2),(664,9,2,0,'How~many~silver~should~you~spend~to~create~a~guild?','500,000','800,000','1,000,000','1,500,000',3),(665,9,2,0,'Guild~members~can~quit~the~guild~by~donating:','10,000~silver','20,000~silver','30,000~silver','40,000~silver',2),(666,9,2,0,'The~name~of~the~guild~branch~cannot~be~over:','5~bytes','6~bytes','7~bytes','8~bytes',2),(667,9,2,0,'The~reward~for~the~guild~war~is:','1000~CP